class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError(f"Cannot roll {pins} pins")

        starts = self._frame_starts()
        if len(starts) >= 10:
            # Frame 10: enforce its special pin limits.
            tenth = self.rolls[starts[9]:]
            if len(tenth) == 1 and tenth[0] != 10 and pins > 10 - tenth[0]:
                raise ValueError("Cannot score more than 10 pins in a frame")
            if (
                len(tenth) == 2
                and tenth[0] != 10
                and tenth[1] != 10
                and pins > 10 - tenth[1]
            ):
                raise ValueError("Cannot score more than 10 pins in a frame")
        elif len(starts) > 0:
            # Frames 1-9: the two rolls of a frame cannot exceed 10 pins.
            first = self.rolls[starts[-1]]
            if len(self.rolls) - starts[-1] == 1 and pins > 10 - first:
                raise ValueError("Cannot score more than 10 pins in a frame")

        if self._game_over():
            raise ValueError("Cannot roll after the game is over")

        self.rolls.append(pins)

    def score(self):
        if not self._game_over():
            raise ValueError("Cannot score an incomplete game")

        starts = self._frame_starts()
        total = 0
        for frame in range(10):
            i = starts[frame]
            if frame < 9:
                if self.rolls[i] == 10:
                    total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                elif self.rolls[i] + self.rolls[i + 1] == 10:
                    total += 10 + self.rolls[i + 2]
                else:
                    total += self.rolls[i] + self.rolls[i + 1]
            else:
                total += sum(self.rolls[i:])
        return total

    def _frame_starts(self):
        """Return the index in `rolls` where each frame begins."""
        starts = []
        i = 0
        while i < len(self.rolls):
            starts.append(i)
            i += 1 if self.rolls[i] == 10 else 2
        return starts

    def _game_over(self):
        starts = self._frame_starts()
        if len(starts) < 10:
            return False
        tenth = self.rolls[starts[9]:]
        if len(tenth) < 2:
            return False
        if tenth[0] == 10 or tenth[0] + tenth[1] == 10:
            return len(tenth) == 3
        return len(tenth) == 2

